$ErrorActionPreference='Continue'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
$wt='C:\Users\Xxkan\AppData\Local\Temp\mhw-smart-pack-salvage-a1'
$branch='reconcile/smart-pack-current-main-20260929'
Set-Location $repo
git fetch origin --prune
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
if(Test-Path $wt){ git worktree remove --force $wt | Out-Null }
git show-ref --verify --quiet "refs/heads/$branch"
if($LASTEXITCODE -eq 0){ git branch -D $branch | Out-Null }
git worktree add -b $branch $wt origin/main
if($LASTEXITCODE -ne 0){ throw 'worktree add failed' }
Set-Location $wt

$files=@(
 'src/MhwModManager.Core/SmartPackPlanner.cs',
 'tests/MhwModManager.Tests/SmartPackPlannerTests.cs'
)
foreach($f in $files){
  git checkout origin/agent/smart-pack-planner-core -- $f
  if($LASTEXITCODE -ne 0){ throw "failed to salvage $f" }
}
git add -- $files
git commit -m "Integrate Smart Pack planning core onto current main"
if($LASTEXITCODE -ne 0){ throw 'commit failed' }

& dotnet test 'tests\MhwModManager.Tests\MhwModManager.Tests.csproj' -c Release --filter 'FullyQualifiedName~SmartPackPlanner'
if($LASTEXITCODE -ne 0){ throw 'SmartPackPlanner focused tests failed' }
& dotnet test 'tests\MhwModManager.Tests\MhwModManager.Tests.csproj' -c Release
if($LASTEXITCODE -ne 0){ throw 'Core unit tests failed' }

$tries=0
while($tries -lt 4){
  $tries++
  git fetch origin main
  if($LASTEXITCODE -ne 0){ throw 'fetch main failed' }
  $remote=(git rev-parse origin/main | Out-String).Trim()
  git merge-base --is-ancestor origin/main HEAD
  if($LASTEXITCODE -ne 0){
    git rebase origin/main
    if($LASTEXITCODE -ne 0){ git rebase --abort | Out-Null; throw 'rebase onto moving main failed' }
    & dotnet test 'tests\MhwModManager.Tests\MhwModManager.Tests.csproj' -c Release
    if($LASTEXITCODE -ne 0){ throw 'post-rebase Core unit tests failed' }
  }
  $final=(git rev-parse HEAD | Out-String).Trim()
  git push origin 'HEAD:main'
  if($LASTEXITCODE -eq 0){
    git fetch origin main | Out-Null
    $verified=(git rev-parse origin/main | Out-String).Trim()
    if($verified -eq $final){
      [ordered]@{status='integrated';final_main=$final;remote_main=$verified;files=$files;focused_tests='pass';core_tests='pass';tries=$tries}|ConvertTo-Json -Depth 4
      exit 0
    }
  }
}
throw 'main kept moving; safe push did not converge after retries'
